import math, random

def normal_cdf(z):
    return 0.5 * (1 + math.erf(z / math.sqrt(2)))

for k in (1, 2, 3):
    print(f"within {k} sd: {normal_cdf(k) - normal_cdf(-k):.4f}")    # 0.6827, 0.9545, 0.9973

random.seed(6)                                                          # 12 random left/right bounces
board = [sum(random.choice((0, 1)) for _ in range(12)) for _ in range(20_000)]
for slot in range(13):
    print(f"{slot:2d} {'#' * (board.count(slot) // 100)}")

import math

def binom_pmf(n, p, k):
    return math.comb(n, k) * p ** k * (1 - p) ** (n - k)

n, p = 20, 0.5
for k in range(6, 15):
    print(f"{k:2d} {'#' * round(binom_pmf(n, p, k) * 200)} {binom_pmf(n, p, k):.4f}")

print(round(sum(binom_pmf(20, 0.5, k) for k in range(15, 21)), 4), "chance of 15 or more heads")     # 0.0207

import math

def poisson_pmf(lam, k):
    return lam ** k * math.exp(-lam) / math.factorial(k)

lam = 3.0
for k in range(0, 10):
    print(f"{k} emails: {'#' * round(poisson_pmf(lam, k) * 100)} {poisson_pmf(lam, k):.3f}")
print("P(at least 8 in an hour) =", round(1 - sum(poisson_pmf(lam, k) for k in range(8)), 4))
print("P(none in an hour) =", round(poisson_pmf(lam, 0), 4))

import math, random

random.seed(14)
total = 0
for n in range(1, 100_001):
    total += random.randint(1, 6)
    if n in (10, 100, 1_000, 10_000, 100_000):
        print(f"{n:>7d} rolls: average {total / n:.4f} (expected 3.5)")

total = 0.0
for n in range(1, 100_001):
    total += math.tan(math.pi * (random.random() - 0.5))          # a Cauchy draw
    if n in (100, 10_000, 100_000):
        print(f"Cauchy, {n:>7d} draws: average {total / n:+.3f}")
